import React, { useState } from 'react';

const AddExpense = ({ trip, expenses, setExpenses }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [paidBy, setPaidBy] = useState('');

  const handleAddExpense = () => {
    if (!description || !amount || !paidBy) return;

    const newExpense = {
      id: Date.now(),
      description,
      amount: parseFloat(amount),
      paidBy
    };

    setExpenses(prev => [...prev, newExpense]);

    setDescription('');
    setAmount('');
    setPaidBy('');
  };

  // Get a flat list of all family members with labels
  const getAllMembers = () => {
    if (!trip || !trip.families) return [];

    return trip.families.flatMap((family, i) => [
      { name: family.head, label: `${family.head} (Head)` },
      ...family.members.map((member, j) => ({
        name: member,
        label: `${member} (Member of ${family.head})`
      }))
    ]);
  };

  const members = getAllMembers();

  const styles = {
    container: {
      border: '1px solid #ccc',
      padding: '15px',
      borderRadius: '8px',
      marginBottom: '20px'
    },
    heading: {
      fontSize: '18px',
      fontWeight: 'bold',
      marginBottom: '10px'
    },
    input: {
      marginRight: '10px',
      padding: '6px',
      borderRadius: '4px',
      border: '1px solid #ccc'
    },
    button: {
      padding: '6px 12px',
      borderRadius: '4px',
      border: 'none',
      backgroundColor: '#007bff',
      color: 'white',
      cursor: 'pointer'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.heading}>Add Expense</div>
      <input
        type="text"
        placeholder="Description"
        style={styles.input}
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />
      <input
        type="number"
        placeholder="Amount"
        style={styles.input}
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
      />
      <select
        style={styles.input}
        value={paidBy}
        onChange={(e) => setPaidBy(e.target.value)}
      >
        <option value="">Select Payer</option>
        {members.map((member, idx) => (
          <option key={idx} value={member.name}>
            {member.label}
          </option>
        ))}
      </select>
      <button style={styles.button} onClick={handleAddExpense}>
        Add
      </button>
    </div>
  );
};

export default AddExpense;
